    S.c0[i]=Math.max(0, 0.62-3.2*((dx+0.15)*(dx+0.15)+(dy+0.05)*(dy+0.05)));
    S.c1[i]=Math.max(0, 0.62-3.2*((dx-0.16)*(dx-0.16)+(dy-0.08)*(dy-0.08)));
    S.c2[i]=Math.max(0, 0.62-3.2*(dx*dx+(dy+0.17)*(dy+0.17)));
