const GN=GW*GH, c0=S.c0,c1=S.c1,c2=S.c2, t0=S.t0,t1=S.t1,t2=S.t2, vx=S.vx,vy=S.vy,psi=S.psi, buf=S.buf;

// dt guard (tolerate t0 resets / backward jumps)
