// ---- 1. velocity = curl of a TWO-SCALE noise stream-function (fine ribbons + coarse stir) => divergence-free ----
const zt=K.t*(0.045+P.speed*0.055)+S.noff;             // REAL-TIME drift -> motion floor (never re-phases)
const nsc=2.4/Math.max(0.4,P.scale);                   // swirl size (bigger scale = broader eddies)
