  const ang=K.t*(0.22+q*0.1)+q*2.399, rad=(isBloom?0.1:0.24)+0.17*Math.sin(K.t*0.07+q*1.7);
  const ix=Math.round((0.5+(P.x-0.5)*0.6+Math.cos(ang)*rad)*GW);
  const iy=Math.round((0.5+(P.y-0.5)*0.6+Math.sin(ang)*rad)*GH);
  const rr=(bloomHit?4:1)+Math.round(clp(P.density,0,1)*2);
  const chan=q%3;
  for(let dy=-rr;dy<=rr;dy++)for(let dx=-rr;dx<=rr;dx++){
    const gx=ix+dx, gy=iy+dy; if(gx<0||gx>=GW||gy<0||gy>=GH)continue;
